"use strict";
const PLAN={step:1,college:"",major:"",targetIds:new Set(),statuses:{},view:"onboarding",query:"",campusQuery:"",editing:false,scenario:"custom",baseline:null};
const COLLEGES=[{id:"district",name:"San Diego Community College District"},{id:"city",name:"San Diego City College"},{id:"mesa",name:"San Diego Mesa College"},{id:"miramar",name:"San Diego Miramar College"},{id:"continuing",name:"San Diego College of Continuing Education"}];
const CAMPUSES=[{"id":"ucb","name":"UC Berkeley","system":"UC"},{"id":"ucd","name":"UC Davis","system":"UC"},{"id":"uci","name":"UC Irvine","system":"UC"},{"id":"ucla","name":"UCLA","system":"UC"},{"id":"ucm","name":"UC Merced","system":"UC"},{"id":"ucr","name":"UC Riverside","system":"UC"},{"id":"ucsd","name":"UC San Diego","system":"UC"},{"id":"ucsb","name":"UC Santa Barbara","system":"UC"},{"id":"ucsc","name":"UC Santa Cruz","system":"UC"},{"id":"bakersfield","name":"CSU Bakersfield","system":"CSU"},{"id":"channelislands","name":"CSU Channel Islands","system":"CSU"},{"id":"chico","name":"Chico State","system":"CSU"},{"id":"dominguez","name":"CSU Dominguez Hills","system":"CSU"},{"id":"eastbay","name":"CSU East Bay","system":"CSU"},{"id":"fresno","name":"Fresno State","system":"CSU"},{"id":"fullerton","name":"CSU Fullerton","system":"CSU"},{"id":"humboldt","name":"Cal Poly Humboldt","system":"CSU"},{"id":"longbeach","name":"CSU Long Beach","system":"CSU"},{"id":"losangeles","name":"Cal State Los Angeles","system":"CSU"},{"id":"monterey","name":"CSU Monterey Bay","system":"CSU"},{"id":"northridge","name":"CSU Northridge","system":"CSU"},{"id":"pomona","name":"Cal Poly Pomona","system":"CSU"},{"id":"sacramento","name":"Sacramento State","system":"CSU"},{"id":"sanbernardino","name":"CSU San Bernardino","system":"CSU"},{"id":"sdsu","name":"San Diego State","system":"CSU"},{"id":"sfsu","name":"San Francisco State","system":"CSU"},{"id":"sjsu","name":"San José State","system":"CSU"},{"id":"slo","name":"Cal Poly San Luis Obispo","system":"CSU"},{"id":"csusm","name":"CSU San Marcos","system":"CSU"},{"id":"sonoma","name":"Sonoma State","system":"CSU"},{"id":"stanislaus","name":"Stanislaus State","system":"CSU"}];
const MAJORS=["Computer Science","Computer Engineering","Mathematics","Engineering","Business Administration","Biology","Psychology","Economics","Undecided"];
const STATUS_LABELS={none:"Not added",completed:"Completed",registered:"Registered",planning:"Planning"};
const escapeHTML=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const collegeName=()=>COLLEGES.find(c=>c.id===PLAN.college)?.name||"SDCCD";
const chosenCampuses=()=>CAMPUSES.filter(c=>PLAN.targetIds.has(c.id));
const statusOf=id=>PLAN.statuses[id]||"none";
const selectedRecords=()=>COURSES.filter(c=>statusOf(c.id)!=="none");
const isCS=()=>PLAN.major.trim().toLowerCase()==="computer science";
function selectionCounts(){const r={completed:0,registered:0,planning:0,units:0};for(const c of selectedRecords()){r[statusOf(c.id)]++;r.units+=c.units}return r}
function statusOptions(id){return Object.entries(STATUS_LABELS).map(([v,label])=>'<option value="'+v+'" '+(statusOf(id)===v?"selected":"")+'>'+label+'</option>').join("")}
function wizardFrame(body){document.getElementById("onboarding").innerHTML='<header class="onboard-header"><a class="brand" href="#"><span class="brand-mark">↗</span><span>transfer<span class="brand-light">copilot</span></span></a><div><span class="demo-tag">SAN DIEGO PILOT</span>'+(PLAN.editing?'<button class="button subtle" data-wizard-action="cancel-edit">Return to my plan</button>':'')+'</div></header><div class="workflow-shell"><nav class="workflow-progress" aria-label="Transfer planning progress"><ol class="workflow-steps">'+["College","Destinations","Major","Coursework"].map((label,i)=>'<li class="'+(PLAN.step===i+1?"current":PLAN.step>i+1?"done":"upcoming")+'" '+(PLAN.step===i+1?'aria-current="step"':'')+'><span class="workflow-number" aria-hidden="true">'+(i+1)+'</span><div class="workflow-label">'+label+'<small>'+(PLAN.step===i+1?"In progress":PLAN.step>i+1?"✓ Complete":"Up next")+'</small></div><span class="sr-only">Step '+(i+1)+'</span></li>').join("")+'</ol></nav><main id="onboarding-main" class="onboard-main" tabindex="-1"><div class="eyebrow">STEP '+String(PLAN.step).padStart(2,"0")+' / 04</div>'+body+'</main><p class="workflow-disclaimer">A planning demo, not academic advice. Official facts and demo assumptions stay separate.</p></div>'}
function nextActions(label){return '<div id="wizard-error" role="alert"></div><div class="wizard-actions"><button class="button subtle" type="button" data-wizard-action="back">← Back</button><button class="button navy" type="submit">'+label+' <span>→</span></button></div>'}
function renderOnboarding(focus=false){document.body.dataset.view="onboarding";document.querySelector(".skip").href="#onboarding-main";
if(PLAN.step===1)wizardFrame('<h2>Where are you studying?</h2><p class="step-intro">Where are you starting your transfer journey?</p><form id="profile-form"><fieldset class="college-picker"><legend class="field-label">Current college</legend><div class="college-options">'+COLLEGES.map(c=>'<label class="college-choice"><input type="radio" name="home-college" value="'+c.id+'" '+(PLAN.college===c.id?'checked':'')+' required>'+schoolBadge(c.id)+'<span>'+c.name+'</span></label>').join("")+'</div></fieldset><p class="field-help">Only SDCCD and its colleges are included. Noncredit Continuing Education courses are not evaluated in this credit-transfer demo.</p><div class="privacy-note"><span>◈</span><p><strong>Your information stays in this tab.</strong> We do not send your answers to a server or retain them after refresh. No name or account needed.</p></div><div id="wizard-error" role="alert"></div><div class="wizard-actions"><span>About 2 minutes</span><button class="button navy" type="submit">Choose my destinations →</button></div></form>');
if(PLAN.step===2){wizardFrame('<h2>Where could you go?</h2><p class="step-intro">Choose one or more UC or CSU campuses to compare.</p><form id="targets-form"><div class="campus-search-row"><label class="search-field"><span aria-hidden="true">⌕</span><input type="search" id="campus-search" placeholder="Search a campus" aria-label="Search UC and CSU campuses" value="'+escapeHTML(PLAN.campusQuery)+'"></label><span id="campus-selected-count"></span></div><div class="selected-campus-chips" id="selected-campus-chips"></div><div id="campus-picker"></div><p class="field-help">UC San Francisco is graduate-only and is not an undergraduate transfer option. CSU’s current directory lists 22 universities.</p><p class="directory-links"><a href="https://www.universityofcalifornia.edu/about-uc/campuses-locations" target="_blank" rel="noopener noreferrer">UC directory ↗</a><a href="https://www.calstate.edu/attend/campuses" target="_blank" rel="noopener noreferrer">CSU directory ↗</a></p>'+nextActions("Choose my major")+'</form>');renderCampusPicker()}
if(PLAN.step===3)wizardFrame('<h2>What would you like to study?</h2><p class="step-intro">Tell us your intended major. You can change it later.</p><form id="major-form"><label class="field-label" for="intended-major">Intended major</label><input id="intended-major" class="field-input" list="major-options" maxlength="100" placeholder="e.g. Computer Science" value="'+escapeHTML(PLAN.major)+'" required><datalist id="major-options">'+MAJORS.map(m=>'<option value="'+m+'"></option>').join("")+'</datalist><div class="major-examples">'+MAJORS.slice(0,6).map(m=>'<button class="choice-chip" type="button" data-major-choice="'+m+'">'+m+'</button>').join("")+'</div><div class="privacy-note"><span>i</span><p><strong>Computer Science has the richest demo.</strong> Other majors work through the full flow, but major-specific matches may be unavailable. Selecting a major does not confirm that every chosen campus offers it.</p></div>'+nextActions("Add my coursework")+'</form>');
if(PLAN.step===4){wizardFrame('<h2>Bring your coursework into view.</h2><p class="step-intro">Mark what you’ve completed, registered for, or are considering.</p><form id="courses-form"><div class="catalog-scope"><strong>SDCCD starter catalog · Mesa examples</strong><p>These 7 verified course examples are at San Diego Mesa College, even if your home college is different. Mark only Mesa coursework here. City, Miramar and noncredit catalogs are linked below; their course lists are not imported yet.</p></div><label class="search-field wizard-course-search"><span aria-hidden="true">⌕</span><input type="search" id="wizard-course-search" placeholder="Search course code or title" aria-label="Search coursework" value="'+escapeHTML(PLAN.query)+'"></label><div class="status-legend"><span><i class="status-dot completed"></i>Completed: finished</span><span><i class="status-dot registered"></i>Registered: enrolled, not finished</span><span><i class="status-dot planning"></i>Planning: considering</span></div><div id="wizard-course-list"></div><div id="course-selection-summary" class="selection-summary" role="status"></div><p class="directory-links"><a href="https://www.sdccd.edu/students/college-catalogs/" target="_blank" rel="noopener noreferrer">All SDCCD catalogs ↗</a><a href="'+SOURCES.classSearch+'" target="_blank" rel="noopener noreferrer">Official class search ↗</a></p><label class="empty-history"><input type="checkbox" id="no-coursework"> I haven’t added any coursework yet—start with an empty plan.</label><p class="field-help">One status per course. Registered and planned work never count as completed. Sources and remaining checks will be visible in your plan.</p>'+nextActions(PLAN.editing?"Update my plan":"Build my transfer plan")+'</form>');renderWizardCourses()}
if(focus){document.getElementById("onboarding-main").focus({preventScroll:true});window.scrollTo({top:0,behavior:"auto"})}}
function renderCampusPicker(){const q=PLAN.campusQuery.trim().toLowerCase();document.getElementById("campus-picker").innerHTML=["UC","CSU"].map(system=>{const list=CAMPUSES.filter(c=>c.system===system&&(!q||c.name.toLowerCase().includes(q)||c.id.includes(q)));return'<fieldset class="campus-group"><legend>'+system+' <span>'+ (system==="UC"?"University of California":"California State University")+'</span></legend><div class="campus-options">'+list.map(c=>'<label class="campus-choice '+(PLAN.targetIds.has(c.id)?"checked":"")+'"><input type="checkbox" value="'+c.id+'" data-wizard-campus="'+c.id+'" '+(PLAN.targetIds.has(c.id)?"checked":"")+'>'+schoolBadge(c.id)+'<span>'+c.name+'</span></label>').join("")+'</div>'+(list.length?"":'<p class="field-help">No matching '+system+' campus.</p>')+'</fieldset>'}).join("");document.getElementById("campus-selected-count").textContent=PLAN.targetIds.size+" selected";document.getElementById("selected-campus-chips").innerHTML=chosenCampuses().map(c=>'<button type="button" class="selected-chip" data-remove-campus="'+c.id+'" aria-label="Remove '+c.name+'">'+schoolBadge(c.id)+c.name+' <span>×</span></button>').join("")}
function renderWizardCourses(){const q=PLAN.query.trim().toLowerCase();const list=COURSES.filter(c=>(c.code+" "+c.title).toLowerCase().includes(q));document.getElementById("wizard-course-list").innerHTML=list.length?list.map(c=>'<div class="wizard-course-row"><div><strong>'+c.code+'</strong><span>'+c.title+'</span><small class="school-inline">'+schoolBadge("mesa")+'Mesa · '+c.units+' units · 2026–27 catalog</small></div><label class="status-select-label"><span class="sr-only">Status for '+c.code+'</span><select data-wizard-status="'+c.id+'" aria-label="Status for '+c.code+'">'+statusOptions(c.id)+'</select></label></div>').join(""):'<div class="empty-state"><h3>No courses match this sample.</h3><p>Try a different search or use the official catalog links below.</p></div>';updateSelectionSummary()}
function updateSelectionSummary(){const s=selectionCounts();document.getElementById("course-selection-summary").textContent=s.completed+" completed · "+s.registered+" registered · "+s.planning+" planning";const empty=document.getElementById("no-coursework");if(selectedRecords().length){empty.checked=false;empty.disabled=true}else empty.disabled=false}
function wizardError(message){const el=document.getElementById("wizard-error");el.className="field-error";el.textContent=message;el.scrollIntoView({block:"nearest"})}
function showDashboard(){PLAN.view="dashboard";document.body.dataset.view="dashboard";document.querySelector(".skip").href="#main";if(!PLAN.baseline)PLAN.baseline={...PLAN.statuses};render();window.scrollTo({top:0,behavior:"auto"});document.querySelector("#main h1").setAttribute("tabindex","-1");document.querySelector("#main h1").focus({preventScroll:true})}
function beginEdit(step=1){PLAN.editSnapshot={college:PLAN.college,major:PLAN.major,targetIds:[...PLAN.targetIds],statuses:{...PLAN.statuses}};PLAN.editing=true;PLAN.step=step;PLAN.query="";PLAN.campusQuery="";renderOnboarding(true)}
function startOver(){PLAN.step=1;PLAN.college="";PLAN.major="";PLAN.targetIds=new Set();PLAN.statuses={};PLAN.baseline=null;PLAN.query="";PLAN.campusQuery="";PLAN.editing=false;PLAN.view="onboarding";delete PLAN.editSnapshot;renderOnboarding(true)}
document.addEventListener("submit",event=>{const id=event.target.id;if(!["profile-form","targets-form","major-form","courses-form"].includes(id))return;event.preventDefault();
if(id==="profile-form"){const college=document.querySelector('input[name="home-college"]:checked')?.value;if(!COLLEGES.some(c=>c.id===college))return wizardError("Choose a college in SDCCD.");PLAN.college=college;PLAN.step=2}
if(id==="targets-form"){if(!PLAN.targetIds.size)return wizardError("Choose at least one UC or CSU campus.");PLAN.step=3}
if(id==="major-form"){const major=document.getElementById("intended-major").value.trim();if(!major)return wizardError("Enter an intended major, or choose Undecided.");PLAN.major=major;PLAN.step=4}
if(id==="courses-form"){if(!selectedRecords().length&&!document.getElementById("no-coursework").checked)return wizardError("Choose a status for at least one course, or select the empty-plan option.");PLAN.baseline={...PLAN.statuses};PLAN.scenario="custom";PLAN.editing=false;return showDashboard()}
renderOnboarding(true)});
document.addEventListener("input",e=>{if(e.target.id==="campus-search"){PLAN.campusQuery=e.target.value;renderCampusPicker()}if(e.target.id==="wizard-course-search"){PLAN.query=e.target.value;renderWizardCourses()}});
document.addEventListener("change",e=>{if(e.target.dataset.wizardCampus){e.target.checked?PLAN.targetIds.add(e.target.dataset.wizardCampus):PLAN.targetIds.delete(e.target.dataset.wizardCampus);renderCampusPicker()}if(e.target.dataset.wizardStatus){PLAN.statuses[e.target.dataset.wizardStatus]=e.target.value;updateSelectionSummary()}});
document.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(b.dataset.removeCampus){PLAN.targetIds.delete(b.dataset.removeCampus);renderCampusPicker()}if(b.dataset.majorChoice){document.getElementById("intended-major").value=b.dataset.majorChoice;document.getElementById("intended-major").focus()}const a=b.dataset.wizardAction;if(a==="back"){if(PLAN.step===3)PLAN.major=document.getElementById("intended-major").value.trim();PLAN.step=Math.max(1,PLAN.step-1);renderOnboarding(true)}if(a==="cancel-edit"){Object.assign(PLAN,PLAN.editSnapshot);PLAN.targetIds=new Set(PLAN.editSnapshot.targetIds);PLAN.editing=false;showDashboard()}});
renderOnboarding();
